use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        // result.0 and result.1 have dimensions len(y) x len(x)
        result.0.len() == y.len(),
        forall|row: usize| row < y.len() ==> result.0[row].len() == x.len(),
        result.1.len() == y.len(),
        forall|row: usize| row < y.len() ==> result.1[row].len() == x.len(),

        // at (i, j), first matrix equals x[j]
        forall|i: usize, j: usize| (i < y.len() && j < x.len()) ==> result.0[i][j] == x[j],

        // at (i, j), second matrix equals y[i]
        forall|i: usize, j: usize| (i < y.len() && j < x.len()) ==> result.1[i][j] == y[i],
{
    let mut grid_x: Vec<Vec<f32>> = Vec::new();
    let mut grid_y: Vec<Vec<f32>> = Vec::new();

    let mut i: usize = 0;
    while i < y.len()
        invariant
            i <= y.len(),
            grid_x.len() == i,
            grid_y.len() == i,
            forall|row: usize| row < i ==> grid_x[row].len() == x.len(),
            forall|row: usize| row < i ==> grid_y[row].len() == x.len(),
            forall|row: usize, col: usize| (row < i && col < x.len()) ==> grid_x[row][col] == x[col],
            forall|row: usize, col: usize| (row < i && col < x.len()) ==> grid_y[row][col] == y[row],
        decreases y.len() - i,
    {
        // Construct one row for grid_x: replicate x
        let mut row_x: Vec<f32> = Vec::new();
        let mut j: usize = 0;
        while j < x.len()
            invariant
                j <= x.len(),
                row_x.len() == j,
                forall|col: usize| col < j ==> row_x[col] == x[col],
            decreases x.len() - j,
        {
            row_x.push(x[j]);
            j += 1;
        }

        // Construct one row for grid_y: replicate y[i]
        let mut row_y: Vec<f32> = Vec::new();
        let mut k: usize = 0;
        while k < x.len()
            invariant
                k <= x.len(),
                row_y.len() == k,
                forall|col: usize| col < k ==> row_y[col] == y[i],
            decreases x.len() - k,
        {
            row_y.push(y[i]);
            k += 1;
        }

        grid_x.push(row_x);
        grid_y.push(row_y);
        i += 1;
    }

    (grid_x, grid_y)
}

}
